// InnerTube text structures: formatted text (simpleText or runs), the
// accessibility holder, and attributed strings (content plus style and
// command runs).

export interface TextRun {
  text: string;
  navigationEndpoint?: unknown;
  bold?: boolean;
  italics?: boolean;
  [key: string]: unknown;
}

export interface FormattedText {
  simpleText?: string;
  runs?: TextRun[];
  accessibility?: AccessibilityHolder;
}

export interface AccessibilityHolder {
  accessibilityData?: { label?: string };
  label?: string;
}

export interface StyleRun {
  startIndex?: number;
  length?: number;
  [key: string]: unknown;
}

export interface CommandRun {
  startIndex?: number;
  length?: number;
  onTap?: unknown;
  [key: string]: unknown;
}

export interface AttributedText {
  content?: string;
  styleRuns?: StyleRun[];
  commandRuns?: CommandRun[];
  [key: string]: unknown;
}

export function getText(text: FormattedText | null | undefined): string {
  if (!text) return "";
  if (text.simpleText != null) return text.simpleText;
  let out = "";
  for (const run of text.runs ?? []) out += run.text;
  return out;
}

export function getRuns(text: FormattedText | null | undefined): TextRun[] {
  if (!text) return [];
  if (text.runs) return text.runs;
  if (text.simpleText != null) return [{ text: text.simpleText }];
  return [];
}

export function accessibilityLabel(holder: { accessibility?: AccessibilityHolder; accessibilityData?: { label?: string } } | null | undefined): string {
  if (!holder) return "";
  const data = holder.accessibility?.accessibilityData ?? holder.accessibilityData;
  return data?.label ?? "";
}

export interface AttributedRange {
  text: string;
  style: StyleRun | null;
  command: CommandRun | null;
}

/** Cuts an attributed string into ranges with one style and command each. */
export function attributedRanges(attributed: AttributedText | null | undefined): AttributedRange[] {
  if (!attributed || typeof attributed.content !== "string") return [];
  const content = attributed.content;
  const styleRuns = attributed.styleRuns ?? [];
  const commandRuns = attributed.commandRuns ?? [];
  if (!styleRuns.length && !commandRuns.length) return [{ text: content, style: null, command: null }];
  const cuts = new Set([0, content.length]);
  for (const r of [...styleRuns, ...commandRuns]) {
    const start = r.startIndex ?? 0;
    cuts.add(start);
    cuts.add(start + (r.length ?? 0));
  }
  const points = [...cuts].filter((p) => p >= 0 && p <= content.length).sort((a, b) => a - b);
  const covers = (r: StyleRun | CommandRun, at: number) => (r.startIndex ?? 0) <= at && at < (r.startIndex ?? 0) + (r.length ?? 0);
  const out: AttributedRange[] = [];
  for (let i = 0; i + 1 < points.length; i++) {
    const start = points[i];
    const end = points[i + 1];
    if (start === end) continue;
    out.push({
      text: content.slice(start, end),
      style: styleRuns.find((r) => covers(r, start)) ?? null,
      command: commandRuns.find((r) => covers(r, start)) ?? null,
    });
  }
  return out;
}
