import { getConfig, type ClientContext } from "../config";
import { post, type ResponseKind } from "./network";

/**
 * The client context of an InnerTube request: a fresh copy of the page
 * config's context, with the current URL, screen size and click tracking.
 */
export function clientContext(clickTrackingParams?: string): ClientContext {
  const context = structuredClone(getConfig().INNERTUBE_CONTEXT);
  const client = context.client;
  client.originalUrl = location.href;
  client.screenWidthPoints = window.innerWidth;
  client.screenHeightPoints = window.innerHeight;
  if (client.mainAppWebInfo) client.mainAppWebInfo.graftUrl = location.href;
  if (clickTrackingParams && context.clickTracking) context.clickTracking.clickTrackingParams = clickTrackingParams;
  return context;
}

export function search(query: string, params?: string): Promise<string> {
  return post("search-init", "/youtubei/v1/search", { context: clientContext(), query, ...(params ? { params } : {}) });
}

/** A continuation request; `kind` says which simulated response answers it. */
export function continuation(kind: ResponseKind, apiPath: string, token: string, clickTrackingParams?: string): Promise<string> {
  return post(kind, apiPath, { context: clientContext(clickTrackingParams), continuation: token });
}

export interface WatchRequest {
  videoId: string;
  playerParams?: string;
  clickTrackingParams?: string;
}

/** The combined player and watch-next request (get_watch). */
export function getWatch({ videoId, playerParams, clickTrackingParams }: WatchRequest): Promise<string> {
  return post("watch", "/youtubei/v1/get_watch", {
    context: clientContext(clickTrackingParams),
    videoId,
    ...(playerParams ? { params: playerParams } : {}),
    racyCheckOk: false,
    contentCheckOk: false,
    playbackContext: {
      contentPlaybackContext: {
        html5Preference: "HTML5_PREF_WANTS",
        lactMilliseconds: "-1",
        signatureTimestamp: 20367,
        autoCaptionsDefaultOn: false,
        autonavState: "STATE_ON",
      },
    },
  });
}

export function browse(browseId: string, params?: string, clickTrackingParams?: string): Promise<string> {
  return post("browse", "/youtubei/v1/browse", { context: clientContext(clickTrackingParams), browseId, ...(params ? { params } : {}) });
}

export interface PlayerRequest {
  videoId: string;
  /** The page URL of the video, which the player reports as the current URL. */
  currentUrl: string;
  clickTrackingParams?: string;
}

/** The player request of an inline player, such as a channel's featured video. */
export function player({ videoId, currentUrl, clickTrackingParams }: PlayerRequest): Promise<string> {
  return post("player", "/youtubei/v1/player", {
    context: clientContext(clickTrackingParams),
    videoId,
    playbackContext: {
      contentPlaybackContext: {
        currentUrl,
        vis: 5,
        splay: false,
        autoCaptionsDefaultOn: false,
        autonavState: "STATE_ON",
        html5Preference: "HTML5_PREF_WANTS",
        signatureTimestamp: 20367,
        autoplay: true,
        autonav: true,
        referer: location.href,
        lactMilliseconds: "-1",
      },
    },
    racyCheckOk: false,
    contentCheckOk: false,
  });
}
