import { resolveRenderer, rendererKey } from "./registry";

/** Renders an InnerTube renderer object with its registered component. */
export function Renderer({ data }: { data: object | null | undefined }) {
  const resolved = resolveRenderer(data);
  if (!resolved) return null;
  const [key, Component] = resolved;
  return <Component data={(data as Record<string, unknown>)[key]} />;
}

/** Renders a list of renderer objects, keyed by their content ids. */
export function RendererList({ items }: { items: readonly object[] | null | undefined }) {
  const seen = new Set<string>();
  return items?.map((item, i) => {
    let key = rendererKey(item, i);
    if (seen.has(key)) key += `#${i}`;
    seen.add(key);
    return <Renderer key={key} data={item} />;
  });
}
