import { QueryClient } from "@tanstack/react-query";

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // The simulated server answers in a fixed order per response kind, so
      // a refetch on window focus would take a later step's response.
      refetchOnWindowFocus: false,
      // The simulated network never fails, so an error comes from processing
      // a response. A retry would not help, and it would take the response
      // of a later step. Components show the error and offer to try again.
      retry: false,
    },
  },
});
