import { useNavigate } from "react-router";
import { endpointHref, flattenCommand, type Endpoint } from "../model/endpoints";
import { useUiStore } from "../state/ui";

const EXPANDED = "ENGAGEMENT_PANEL_VISIBILITY_EXPANDED";

interface ShowPanel {
  panelIdentifier?: string;
  identifier?: { tag?: string };
}

interface ChangePanelVisibility {
  targetId?: string;
  visibility?: string;
}

/**
 * Returns a function that runs an InnerTube command: navigations go through
 * the router, popups to the popup container, and engagement panel commands
 * to the panel state. Service endpoints (playlist edits, shares, signals)
 * have no simulated server and are dropped.
 */
export function useRunCommand(): (command: Endpoint | null | undefined) => void {
  const navigate = useNavigate();
  const openPopup = useUiStore((s) => s.openPopup);
  const setPanelVisible = useUiStore((s) => s.setPanelVisible);
  return (command) => {
    for (const c of flattenCommand(command)) {
      const href = endpointHref(c);
      if (href) {
        navigate(href, { state: { endpoint: c } });
        continue;
      }
      const popup = c.openPopupAction as { popup?: Record<string, unknown> } | undefined;
      if (popup?.popup) {
        const [renderer] = Object.keys(popup.popup);
        if (renderer) openPopup({ kind: "dialog", renderer, data: popup.popup[renderer] });
        continue;
      }
      const show = c.showEngagementPanelEndpoint as ShowPanel | undefined;
      const showId = show?.panelIdentifier ?? show?.identifier?.tag;
      if (showId) {
        setPanelVisible(showId, true);
        continue;
      }
      const change = c.changeEngagementPanelVisibilityAction as ChangePanelVisibility | undefined;
      if (change?.targetId) setPanelVisible(change.targetId, change.visibility === EXPANDED);
    }
  };
}
