import clsx from "clsx";
import styles from "./TouchFeedback.module.css";

export interface TouchFeedbackProps {
  inverse?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

/** The pressed-state layer of tappable surfaces: a stroke and a fill. */
export function TouchFeedback({ inverse = false, className, style }: TouchFeedbackProps) {
  return (
    <div className={clsx(styles.host, inverse && styles.inverse, className)} style={style} aria-hidden="true">
      <div className={styles.stroke} />
      <div className={styles.fill} />
    </div>
  );
}
