import clsx from "clsx";
import type { MouseEvent, ReactNode } from "react";
import { Icon } from "../icon/Icon";
import { TouchFeedback } from "../feedback/TouchFeedback";
import styles from "./ButtonShape.module.css";

export type ButtonStyle = "filled" | "tonal" | "outline" | "text";
export type ButtonType = "mono" | "callToAction" | "overlay" | "suggestive";
export type ButtonSize = "m" | "s" | "xs";

export interface ButtonShapeProps {
  text?: ReactNode;
  icon?: string;
  iconPosition?: "leading" | "trailing";
  buttonStyle?: ButtonStyle;
  type?: ButtonType;
  size?: ButtonSize;
  label?: string;
  title?: string;
  describedBy?: string;
  href?: string;
  disabled?: boolean;
  fullWidth?: boolean;
  pressed?: boolean;
  expanded?: boolean;
  className?: string;
  style?: React.CSSProperties;
  onClick?: (e: MouseEvent<HTMLElement>) => void;
}

/**
 * The design system's button. It renders a <button>, or an <a> with an
 * href; the icon and text order follows iconPosition.
 */
export function ButtonShape({
  text,
  icon,
  iconPosition = "leading",
  buttonStyle = "text",
  type = "mono",
  size = "m",
  label,
  title,
  describedBy,
  href,
  disabled,
  fullWidth,
  pressed,
  expanded,
  className,
  style,
  onClick,
}: ButtonShapeProps) {
  const hasText = text != null && text !== "";
  const iconOnly = !!icon && !hasText;
  const classes = clsx(
    styles.button,
    styles[buttonStyle],
    styles[type],
    styles[`size-${size}`],
    iconOnly ? styles.iconButton : icon && (iconPosition === "leading" ? styles.iconLeading : styles.iconTrailing),
    disabled && styles.disabled,
    fullWidth && styles.fullWidth,
    className,
  );
  const iconEl = icon ? (
    <div className={styles.icon}>
      <Icon icon={icon} />
    </div>
  ) : null;
  const content = (
    <>
      {iconPosition === "leading" && iconEl}
      {hasText && <div className={styles.text}>{text}</div>}
      {iconPosition === "trailing" && iconEl}
      <TouchFeedback inverse={buttonStyle === "filled"} />
      {(buttonStyle === "tonal" || buttonStyle === "outline") && <span className={styles.light} aria-hidden="true" />}
    </>
  );
  if (href && !disabled) {
    return (
      <a className={classes} href={href} aria-label={label} aria-describedby={describedBy} title={title} style={style} onClick={onClick}>
        {content}
      </a>
    );
  }
  return (
    <button
      type="button"
      className={classes}
      aria-label={label}
      aria-describedby={describedBy}
      aria-pressed={pressed}
      aria-expanded={expanded}
      title={title}
      disabled={disabled}
      style={style}
      onClick={onClick}
    >
      {content}
    </button>
  );
}
