import { useEffectEvent, useLayoutEffect, type RefObject } from "react";

// One ResizeObserver for the whole app; each element has one callback.
let observer: ResizeObserver | null = null;
const callbacks = new WeakMap<Element, () => void>();

function sharedObserver(): ResizeObserver {
  observer ??= new ResizeObserver((entries) => {
    for (const entry of entries) callbacks.get(entry.target)?.();
  });
  return observer;
}

/**
 * Calls `onResize` when the element in `ref` mounts, before the browser
 * paints, so that the first frame uses its measurements, and then whenever
 * the element changes size.
 */
export function useResizeObserver(ref: RefObject<Element | null>, onResize: () => void): void {
  const handleResize = useEffectEvent(onResize);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    handleResize();
    const obs = sharedObserver();
    callbacks.set(el, () => handleResize());
    obs.observe(el);
    return () => {
      obs.unobserve(el);
      callbacks.delete(el);
    };
  }, [ref]);
}
