import type { ComponentType } from "react";

// InnerTube responses describe UI as renderer objects keyed by type
// ({videoRenderer: {...}}). Feature modules register a component per key;
// shared renderers register from the components that define them.

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type RendererComponent = ComponentType<{ data: any }>;

const registry = new Map<string, RendererComponent>();

export function registerRenderers(map: Record<string, RendererComponent>): void {
  for (const [key, component] of Object.entries(map)) registry.set(key, component);
}

/** The registered key and component of a renderer object, if any. */
export function resolveRenderer(item: object | null | undefined): [string, RendererComponent] | null {
  if (!item) return null;
  for (const key of Object.keys(item)) {
    const component = registry.get(key);
    if (component) return [key, component];
  }
  return null;
}

/** A stable key for a list item: its content id, else its tracking params. */
export function rendererKey(item: object, index: number): string {
  const resolved = resolveRenderer(item);
  const data = resolved ? ((item as Record<string, unknown>)[resolved[0]] as Record<string, unknown>) : undefined;
  const id = data?.videoId ?? data?.contentId ?? data?.commentId ?? data?.trackingParams ?? (data?.loggingDirectives as { trackingParams?: string } | undefined)?.trackingParams;
  return `${resolved?.[0] ?? "item"}:${typeof id === "string" ? id : index}`;
}
