import clsx from "clsx";
import { Icon } from "../icon/Icon";
import styles from "./BadgeShape.module.css";

export type BadgeStyle = "default" | "thumbnail" | "live" | "verified" | "media" | "simple" | "ad" | "overlayWhite";

export interface BadgeShapeProps {
  text?: string;
  icon?: string;
  badgeStyle?: BadgeStyle;
  label?: string;
  /** Shows only the icon; the text stays for assistive technology. */
  hideText?: boolean;
  className?: string;
}

/** The design system's badge: an optional 12px icon and a short text. */
export function BadgeShape({ text, icon, badgeStyle = "default", label, hideText, className }: BadgeShapeProps) {
  return (
    <div className={clsx(styles.badge, styles[badgeStyle], className)} role="img" aria-label={label || text}>
      {icon && (
        <div className={styles.icon}>
          <Icon icon={icon} size={12} />
        </div>
      )}
      {text != null && <div className={clsx(styles.text, hideText && styles.textHidden)}>{text}</div>}
    </div>
  );
}
