/**
 * Returns `value[key]` if the value is a wrapper object around `key`, else
 * the value itself. InnerTube nests view models under a field name and then
 * under their type name (`likeButtonViewModel: {likeButtonViewModel: {...}}`),
 * but not always both.
 */
export function unwrap<T>(value: unknown, key: string): T | undefined {
  let v = value as Record<string, unknown> | undefined | null;
  while (v && typeof v === "object" && key in v && v[key] && typeof v[key] === "object") v = v[key] as Record<string, unknown>;
  return (v ?? undefined) as T | undefined;
}
