import { useCallback, useSyncExternalStore } from "react";

// A normalized store of the mutable entities that responses deliver in
// frameworkUpdates (like status, subscription state, toggle states). Many
// components read the same entity, so each key has its own subscribers.

type Listener = () => void;

const entities = new Map<string, unknown>();
const listeners = new Map<string, Set<Listener>>();

function notify(key: string) {
  for (const l of listeners.get(key) ?? []) l();
}

export function getEntity<T>(key: string): T | undefined {
  return entities.get(key) as T | undefined;
}

export function setEntity(key: string, value: unknown): void {
  if (entities.get(key) === value) return;
  if (value === undefined) entities.delete(key);
  else entities.set(key, value);
  notify(key);
}

export interface EntityMutation {
  entityKey?: string;
  type?: string;
  payload?: Record<string, unknown>;
}

/** Applies the mutations of an entityBatchUpdate; returns how many applied. */
export function applyEntityMutations(mutations: EntityMutation[]): number {
  let n = 0;
  for (const m of mutations) {
    if (typeof m.entityKey !== "string") continue;
    if (m.type === "ENTITY_MUTATION_TYPE_DELETE") setEntity(m.entityKey, undefined);
    else if (m.payload) {
      const [payloadKey] = Object.keys(m.payload);
      setEntity(m.entityKey, payloadKey ? m.payload[payloadKey] : undefined);
    }
    n++;
  }
  return n;
}

function subscribeKey(key: string, listener: Listener): () => void {
  let set = listeners.get(key);
  if (!set) listeners.set(key, (set = new Set()));
  set.add(listener);
  return () => {
    set.delete(listener);
    if (!set.size) listeners.delete(key);
  };
}

const noop = () => () => {};

/** Reads one entity and re-renders when it changes. */
export function useEntity<T>(key: string | undefined | null): T | undefined {
  const subscribe = useCallback((l: Listener) => (key ? subscribeKey(key, l) : noop()), [key]);
  return useSyncExternalStore(subscribe, () => (key ? (entities.get(key) as T | undefined) : undefined));
}
