import { getConfig } from "../config";
import { flags } from "../flags";
import { clientContext } from "../api/innertube";
import { prepareBody } from "../api/network";
import { track } from "../workload/idle";

// The logging client. Events are queued in memory and sent in batches: when
// the queue holds the maximum batch size (in an idle callback), when the
// debounce timer fires with at least the minimum batch size, or when the
// queue's maximum age is reached. Sending first writes the batch to an
// IndexedDB queue, so that it survives a page unload, then serializes it
// with a client context and gzips it. The simulated server has no logging
// endpoint, so the request is dropped there.

export interface LogOptions {
  timestamp?: number;
  sequenceGroup?: string;
  sendIsolated?: boolean;
}

interface LogEvent {
  eventTimeMs: number;
  context: { lastActivityMs: string; sequence?: { index: number; groupKey: string } };
  [payload: string]: unknown;
}

/** Event counts for tools/verify.mjs. */
const counters = { queued: 0, flushes: 0, batchChars: 0, kinds: {} as Record<string, { count: number; chars: number }> };
(window as unknown as { ytrLogCounters: typeof counters }).ytrLogCounters = counters;

const queue: LogEvent[] = [];
let debounceTimer = 0;
let maxAgeTimer = 0;
let idleFlushRequested = false;
let db: IDBDatabase | null = null;
let batchCounter = 0;
let lastActivityMs = Date.now();
const sequenceIndexes = new Map<string, number>();

for (const type of ["click", "keydown", "scroll", "mousemove"]) {
  window.addEventListener(type, () => (lastActivityMs = Date.now()), { capture: true, passive: true });
}

/** Opens the IndexedDB batch queue. Called once at startup. */
export function openLogQueue(): Promise<void> {
  return new Promise((resolve) => {
    const req = indexedDB.open("ytr-logs", 1);
    req.onupgradeneeded = () => req.result.createObjectStore("batches", { keyPath: "id", autoIncrement: true });
    req.onsuccess = () => {
      db = req.result;
      const tx = db.transaction("batches", "readwrite");
      tx.objectStore("batches").clear();
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
    };
    req.onerror = () => resolve();
  });
}

export function logEvent(name: string, payload: object, options: LogOptions = {}): void {
  const now = Math.round(options.timestamp ?? performance.timeOrigin + performance.now());
  const event: LogEvent = {
    eventTimeMs: now,
    context: { lastActivityMs: String(options.timestamp ? -1 : Date.now() - lastActivityMs) },
    [name]: payload,
  };
  if (options.sequenceGroup) {
    const index = (sequenceIndexes.get(options.sequenceGroup) ?? -1) + 1;
    sequenceIndexes.set(options.sequenceGroup, index);
    event.context.sequence = { index, groupKey: options.sequenceGroup };
  }
  counters.queued++;
  const kind = (counters.kinds[name] ??= { count: 0, chars: 0 });
  kind.count++;
  kind.chars += JSON.stringify(payload).length;
  if (options.sendIsolated) {
    sendBatch([event]);
    return;
  }
  queue.push(event);
  scheduleFlush();
}

function scheduleFlush() {
  const maxBatch = flags.number("web_logging_max_batch", 100);
  if (queue.length >= maxBatch) {
    if (idleFlushRequested) return;
    idleFlushRequested = true;
    track(
      new Promise<void>((resolve) =>
        requestIdleCallback(
          () => {
            idleFlushRequested = false;
            flush();
            resolve();
          },
          { timeout: 3000 },
        ),
      ),
    );
    return;
  }
  if (!maxAgeTimer) maxAgeTimer = window.setTimeout(flush, flags.number("gel_queue_timeout_max_ms", 60000));
  clearTimeout(debounceTimer);
  debounceTimer = window.setTimeout(() => {
    if (queue.length >= flags.number("gel_min_batch_size", 5)) flush();
  }, flags.number("web_gel_debounce_ms", 10000));
}

/** Sends everything queued, in batches of at most 1000 events. */
export function flush(): void {
  clearTimeout(debounceTimer);
  clearTimeout(maxAgeTimer);
  debounceTimer = 0;
  maxAgeTimer = 0;
  while (queue.length) sendBatch(queue.splice(0, 1000));
}

function sendBatch(events: LogEvent[]) {
  counters.flushes++;
  batchCounter = batchCounter ? (batchCounter % 65535) + 1 : 1 + Math.floor((Math.random() * 65535) / 2);
  const request = {
    context: clientContext(),
    events,
    serializedClientEventId: { serializedEventId: getConfig().EVENT_ID, clientCounter: String(batchCounter) },
  };
  if (!db) {
    void send(request, undefined);
    return;
  }
  const tx = db.transaction("batches", "readwrite");
  const put = tx.objectStore("batches").add({ url: "/youtubei/v1/log_event", body: request, timestamp: Date.now(), status: "NEW" });
  track(
    new Promise<void>((resolve) => {
      tx.oncomplete = () => {
        void send(request, put.result as number).then(resolve);
      };
      tx.onerror = () => {
        void send(request, undefined).then(resolve);
      };
    }),
  );
}

async function send(request: object, dbId: number | undefined) {
  const body = JSON.stringify(request);
  counters.batchChars += body.length;
  await track(prepareBody(body));
  if (db && dbId !== undefined) db.transaction("batches", "readwrite").objectStore("batches").delete(dbId);
}
