import clsx from "clsx";
import type { ThumbnailViewModel as ThumbnailData, ButtonViewModel as ButtonData } from "../../model/innertube.gen";
import { unwrap } from "../../model/unwrap";
import { Image } from "../image/Image";
import { ButtonViewModel } from "../button/ButtonViewModel";
import { BadgeShape } from "../badge/BadgeShape";
import styles from "./ThumbnailViewModel.module.css";

export type AspectRatio = "16:9" | "2:3" | "1:1";

interface Overlay {
  thumbnailOverlayButtonViewModel?: { overlayButton?: unknown; position?: string };
  thumbnailOverlayBadgeViewModel?: { thumbnailBadges?: unknown[]; position?: string };
  thumbnailBottomOverlayViewModel?: { progressBar?: { thumbnailOverlayProgressBarViewModel?: { startPercent?: number } }; badges?: unknown[] };
}

interface Badge {
  text?: string;
  rendererContext?: { accessibilityContext?: { label?: string } };
  animatedText?: string;
  badgeStyle?: string;
  icon?: { sources?: Array<{ clientResource?: { imageName?: string } }> };
}

function ThumbnailBadge({ data }: { data: Badge }) {
  const text = data.text ?? data.animatedText;
  const icon = data.icon?.sources?.[0]?.clientResource?.imageName;
  return (
    <div className={styles.badge}>
      {text && (
        <BadgeShape
          text={text}
          icon={icon}
          label={data.rendererContext?.accessibilityContext?.label}
          badgeStyle={data.badgeStyle === "THUMBNAIL_OVERLAY_BADGE_STYLE_LIVE" ? "live" : "thumbnail"}
        />
      )}
    </div>
  );
}

function OverlayView({ overlay }: { overlay: Overlay }) {
  const button = overlay.thumbnailOverlayButtonViewModel;
  if (button) {
    const data = unwrap<ButtonData>(button.overlayButton, "buttonViewModel");
    return (
      <div className={styles.overlayButton}>
        <div className={clsx(styles.buttonContainer, styles.bottomEnd)}>
          <div className={styles.button}>{data && <ButtonViewModel data={data} />}</div>
        </div>
      </div>
    );
  }
  const badges = overlay.thumbnailOverlayBadgeViewModel;
  if (badges) {
    return (
      <div className={clsx(styles.overlayBadges, badges.position === "THUMBNAIL_OVERLAY_BADGE_POSITION_TOP_START" ? styles.topStart : styles.bottomEnd)}>
        {badges.thumbnailBadges?.map((b, i) => {
          const badge = unwrap<Badge>(b, "thumbnailBadgeViewModel");
          return badge ? <ThumbnailBadge key={i} data={badge} /> : null;
        })}
      </div>
    );
  }
  const bottom = overlay.thumbnailBottomOverlayViewModel;
  if (bottom) {
    const progress = bottom.progressBar?.thumbnailOverlayProgressBarViewModel;
    return (
      <div className={styles.bottomOverlay}>
        {!!bottom.badges?.length && (
          <div className={styles.bottomBadges}>
            {bottom.badges.map((b, i) => {
              const badge = unwrap<Badge>(b, "thumbnailBadgeViewModel");
              return badge ? <ThumbnailBadge key={i} data={badge} /> : null;
            })}
          </div>
        )}
        {progress && (
          <div className={styles.progressBar}>
            <div className={styles.progressSegment} style={{ width: `${progress.startPercent ?? 0}%` }} />
          </div>
        )}
      </div>
    );
  }
  return null;
}

export interface ThumbnailViewModelProps {
  data: ThumbnailData | undefined;
  aspectRatio?: AspectRatio;
  width: number;
  /**
   * Fits the image into the frame over a blurred copy of it. By default, a
   * 16:9 frame does this for portrait and square images.
   */
  cinematic?: boolean;
  className?: string;
}

/** A view-model thumbnail: the image and its overlays (buttons, badges, progress). */
export function ThumbnailViewModel({ data, aspectRatio = "16:9", width, cinematic: cinematicProp, className }: ThumbnailViewModelProps) {
  const thumbnail = unwrap<ThumbnailData>(data, "thumbnailViewModel");
  const sources = (thumbnail?.image as { sources?: Array<{ url: string; width?: number; height?: number }> } | undefined)?.sources;
  const first = sources?.[0];
  const cinematic = cinematicProp ?? (aspectRatio === "16:9" && !!first?.width && !!first.height && first.width / first.height <= 1);
  const fit = cinematic ? "contain" : "cover";
  return (
    <div
      className={clsx(
        styles.thumbnail,
        aspectRatio === "16:9" ? styles.ratio16by9 : aspectRatio === "2:3" ? styles.ratio2by3 : styles.ratio1by1,
        cinematic && styles.cinematic,
        className,
      )}
    >
      {cinematic && (
        <div className={styles.blurred}>
          <Image image={sources} width={width} fit={fit} />
        </div>
      )}
      <div className={styles.image}>
        <Image image={sources} width={width} fit={fit} />
      </div>
      {(thumbnail?.overlays as Overlay[] | undefined)?.map((overlay, i) => <OverlayView key={i} overlay={overlay} />)}
    </div>
  );
}
