export interface ThumbnailImage {
  url: string;
  width?: number;
  height?: number;
}

export interface ThumbnailSet {
  thumbnails?: ThumbnailImage[];
}

/** The smallest image at least `width` wide, else the widest one. */
export function pickThumbnail(set: ThumbnailSet | ThumbnailImage[] | null | undefined, width: number): ThumbnailImage | null {
  const list = Array.isArray(set) ? set : set?.thumbnails;
  if (!list?.length) return null;
  let best: ThumbnailImage | null = null;
  for (const t of list) {
    const w = t.width ?? 0;
    if (w >= width && (!best || w < (best.width ?? 0))) best = t;
  }
  if (best) return best;
  return list.reduce((a, b) => ((b.width ?? 0) > (a.width ?? 0) ? b : a));
}
