import clsx from "clsx";
import { pickThumbnail, type ThumbnailImage, type ThumbnailSet } from "./thumbnails";
import styles from "./Image.module.css";

export interface ImageProps {
  image: ThumbnailSet | ThumbnailImage[] | null | undefined;
  /** The display width, for picking a source. */
  width: number;
  fit?: "cover" | "contain";
  fill?: boolean;
  alt?: string;
  className?: string;
  style?: React.CSSProperties;
}

/** A responsive image from an InnerTube thumbnail set, loaded lazily. */
export function Image({ image, width, fit = "cover", fill = true, alt = "", className, style }: ImageProps) {
  const source = pickThumbnail(image, width);
  return (
    <img
      className={clsx(styles.image, fill && styles.fill, fit === "cover" ? styles.cover : styles.contain, className)}
      src={source?.url}
      alt={alt}
      loading="lazy"
      decoding="async"
      style={style}
    />
  );
}

export interface ImgShadowProps {
  image: ThumbnailSet | ThumbnailImage[] | null | undefined;
  width: number;
  className?: string;
}

/** A small image with a placeholder background, such as a channel avatar. */
export function ImgShadow({ image, width, className }: ImgShadowProps) {
  const source = pickThumbnail(image, width);
  return (
    <span className={clsx(styles.shadow, !source && styles.empty, className)}>
      <img className={styles.shadowImage} src={source?.url} alt="" loading="lazy" width={width} />
    </span>
  );
}
