import { logEvent } from "./client";

// Ads control-flow logging. A response's ad opportunity announces slots and
// their layouts; ad surfaces report when a slot or layout enters and exits
// the page. Each transition is one adsClientStateChange event.

export interface AdSlotMetadata {
  slotId?: string;
  slotType?: string;
  slotPhysicalPosition?: number;
  adSlotLoggingData?: { serializedSlotAdServingDataEntry?: string };
}

export interface AdLayoutMetadata {
  layoutId?: string;
  layoutType?: string;
  adLayoutLoggingData?: { serializedAdServingDataEntry?: string };
}

export interface AdOpportunity {
  opportunityType?: string;
  adSlotAndLayoutMetadata?: Array<{ adSlotMetadata?: AdSlotMetadata; adLayoutMetadata?: AdLayoutMetadata[] }>;
}

let eventOrder = 0;
const scheduledSlots = new Set<string>();
const scheduledLayouts = new Set<string>();

function slotData(slot: AdSlotMetadata) {
  return {
    type: slot.slotType,
    controlFlowManagerLayer: "CONTROL_FLOW_MANAGER_LAYER_SURFACE",
    entryTriggerType: "TRIGGER_TYPE_SLOT_ID_ENTERED",
    ...(slot.slotPhysicalPosition != null && slot.slotPhysicalPosition !== 1 ? { slotPhysicalPosition: slot.slotPhysicalPosition } : {}),
  };
}

function logAdEvent(eventType: string, data: { slot?: AdSlotMetadata; layout?: AdLayoutMetadata; opportunityType?: string }) {
  const adClientData: Record<string, unknown> = {};
  if (data.slot) adClientData.slotData = slotData(data.slot);
  if (data.layout) adClientData.layoutData = { type: data.layout.layoutType, controlFlowManagerLayer: "CONTROL_FLOW_MANAGER_LAYER_SURFACE" };
  if (data.opportunityType) adClientData.opportunityData = { opportunityType: data.opportunityType };
  logEvent("adsClientStateChange", {
    adsClientEvent: {
      eventType,
      eventOrder: ++eventOrder,
      adClientData,
      ...(data.slot?.adSlotLoggingData ? { serializedSlotAdServingData: data.slot.adSlotLoggingData.serializedSlotAdServingDataEntry } : {}),
      ...(data.layout?.adLayoutLoggingData ? { serializedAdServingData: data.layout.adLayoutLoggingData.serializedAdServingDataEntry } : {}),
    },
  });
}

const valid = (slot: AdSlotMetadata | undefined): slot is AdSlotMetadata => typeof slot?.slotId === "string" && typeof slot.slotType === "string";
const validLayout = (layout: AdLayoutMetadata | undefined): layout is AdLayoutMetadata =>
  typeof layout?.layoutId === "string" && typeof layout.layoutType === "string";

export function adsOpportunityReceived(command: AdOpportunity): void {
  const type = command.opportunityType;
  if (type) logAdEvent("ADS_CLIENT_EVENT_TYPE_OPPORTUNITY_RECEIVED", { opportunityType: type });
  for (const item of command.adSlotAndLayoutMetadata ?? []) {
    if (!valid(item.adSlotMetadata)) continue;
    logAdEvent("ADS_CLIENT_EVENT_TYPE_SLOT_RECEIVED", { slot: item.adSlotMetadata });
    for (const layout of item.adLayoutMetadata ?? []) {
      if (validLayout(layout)) logAdEvent("ADS_CLIENT_EVENT_TYPE_LAYOUT_RECEIVED", { slot: item.adSlotMetadata, layout });
    }
  }
  if (type) logAdEvent("ADS_CLIENT_EVENT_TYPE_OPPORTUNITY_PROCESSED", { opportunityType: type });
}

export function adSlotEntered(slot: AdSlotMetadata | undefined): void {
  if (!valid(slot)) return;
  if (!scheduledSlots.has(slot.slotId!)) {
    scheduledSlots.add(slot.slotId!);
    logAdEvent("ADS_CLIENT_EVENT_TYPE_SLOT_SCHEDULED", { slot });
  }
  logAdEvent("ADS_CLIENT_EVENT_TYPE_SLOT_ENTERED", { slot });
}

export function adSlotExited(slot: AdSlotMetadata | undefined): void {
  if (!valid(slot)) return;
  logAdEvent("ADS_CLIENT_EVENT_TYPE_SLOT_EXITED", { slot });
  logAdEvent("ADS_CLIENT_EVENT_TYPE_SLOT_UNSCHEDULED", { slot });
  scheduledSlots.delete(slot.slotId!);
}

export function adLayoutEntered(slot: AdSlotMetadata | undefined, layout: AdLayoutMetadata | undefined): void {
  if (!valid(slot) || !validLayout(layout)) return;
  if (!scheduledLayouts.has(layout.layoutId!)) {
    scheduledLayouts.add(layout.layoutId!);
    logAdEvent("ADS_CLIENT_EVENT_TYPE_LAYOUT_SCHEDULED", { slot, layout });
  }
  logAdEvent("ADS_CLIENT_EVENT_TYPE_LAYOUT_ENTERED", { slot, layout });
}

export function adLayoutExited(slot: AdSlotMetadata | undefined, layout: AdLayoutMetadata | undefined): void {
  if (!valid(slot) || !validLayout(layout)) return;
  logAdEvent("ADS_CLIENT_EVENT_TYPE_LAYOUT_EXITED_NORMALLY", { slot, layout });
  scheduledLayouts.delete(layout.layoutId!);
}
