import clsx from "clsx";
import { ICON_PATHS } from "./icons.gen";
import styles from "./Icon.module.css";

export interface IconProps {
  /** An InnerTube icon type, such as "MORE_VERT". */
  icon: string;
  size?: number;
  className?: string;
  /** Makes the icon an image with this label; otherwise it is decorative. */
  label?: string;
}

/** The table key of an icon name; "yt-sys-icons:chevron_right" is CHEVRON_RIGHT. */
function iconKey(icon: string): string {
  const i = icon.indexOf(":");
  return i < 0 ? icon : icon.slice(i + 1).toUpperCase();
}

export function Icon({ icon, size = 24, className, label }: IconProps) {
  const d = ICON_PATHS[iconKey(icon)] ?? ICON_PATHS.MORE_VERT;
  return (
    <span
      className={clsx(styles.wrapper, className)}
      style={{ width: size, height: size }}
      role={label ? "img" : undefined}
      aria-label={label}
    >
      <span className={styles.shape}>
        <div className={styles.box}>
          <svg viewBox="0 0 24 24" width="100%" height="100%" focusable="false" aria-hidden="true" className={styles.svg}>
            <path d={d} />
          </svg>
        </div>
      </span>
    </span>
  );
}
