import clsx from "clsx";
import { useId, useRef } from "react";
import { useIntl, defineMessages } from "react-intl";
import type { MenuRenderer } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { getText, accessibilityLabel } from "../../model/text";
import { useUiStore, type MenuItem } from "../../state/ui";
import { useImpression } from "../../logging/impressions";
import { IconButton } from "../button/IconButton";
import { Renderer } from "../../renderers/Renderer";
import styles from "./Menu.module.css";

const messages = defineMessages({
  actions: { id: "menu.actions", defaultMessage: "Action menu" },
  download: { id: "menu.download", defaultMessage: "Download" },
});

interface MenuItemData {
  menuServiceItemRenderer?: { text?: { runs?: Array<{ text: string }>; simpleText?: string }; icon?: { iconType?: string }; serviceEndpoint?: unknown; hasSeparator?: boolean; trackingParams?: string };
  menuNavigationItemRenderer?: { text?: { runs?: Array<{ text: string }>; simpleText?: string }; icon?: { iconType?: string }; navigationEndpoint?: unknown; trackingParams?: string };
  menuServiceItemDownloadRenderer?: { serviceEndpoint?: unknown; trackingParams?: string };
}

/** The popup entries of a menu's items. */
export function menuItems(items: MenuItemData[] | undefined, downloadText: string): MenuItem[] {
  const out: MenuItem[] = [];
  for (const item of items ?? []) {
    const service = item.menuServiceItemRenderer;
    const nav = item.menuNavigationItemRenderer;
    const download = item.menuServiceItemDownloadRenderer;
    if (service) {
      out.push({ text: getText(service.text), icon: service.icon?.iconType, command: service.serviceEndpoint as Endpoint, hasSeparator: service.hasSeparator, trackingParams: service.trackingParams });
    } else if (nav) {
      out.push({ text: getText(nav.text), icon: nav.icon?.iconType, command: nav.navigationEndpoint as Endpoint, trackingParams: nav.trackingParams });
    } else if (download) {
      out.push({ text: downloadText, icon: "OFFLINE_DOWNLOAD", command: download.serviceEndpoint as Endpoint, trackingParams: download.trackingParams });
    }
  }
  return out;
}

interface FlexibleItem {
  menuFlexibleItemRenderer?: { menuItem?: MenuItemData; topLevelButton?: object };
}

export interface MenuProps {
  data: MenuRenderer;
  className?: string;
  /**
   * Shows the flexible items as buttons. Without room for them, they are
   * entries at the top of the popup instead.
   */
  showFlexibleItems?: boolean;
}

/**
 * A renderer's action menu: its top-level buttons, then a button that opens
 * the remaining items in a popup.
 */
export function Menu({ data, className, showFlexibleItems = false }: MenuProps) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const popupOwner = useId();
  const popupOpen = useUiStore((s) => s.popup?.kind === "menu" && s.popup.owner === popupOwner);
  const openPopup = useUiStore((s) => s.openPopup);
  const label = accessibilityLabel(data.accessibility as { accessibilityData?: { label?: string } }) || intl.formatMessage(messages.actions);
  const flexible = ((data.flexibleItems ?? []) as FlexibleItem[]).flatMap((f) => (f.menuFlexibleItemRenderer ? [f.menuFlexibleItemRenderer] : []));
  const popupItems = [...(showFlexibleItems ? [] : flexible.flatMap((f) => (f.menuItem ? [f.menuItem] : []))), ...((data.items ?? []) as MenuItemData[])];
  return (
    <div ref={ref} className={clsx(styles.menu, className)}>
      <div className={styles.topLevelButtons}>
        {data.topLevelButtons?.map((button, i) => (
          <Renderer key={i} data={button} />
        ))}
      </div>
      <div className={styles.flexibleItems}>
        {showFlexibleItems && flexible.map((f, i) => <Renderer key={i} data={f.topLevelButton} />)}
      </div>
      {popupItems.length > 0 && (
        <IconButton
          icon="MORE_VERT"
          label={label}
          hasPopup
          expanded={popupOpen}
          onClick={(e) => {
            openPopup(
              {
                kind: "menu",
                items: menuItems(popupItems, intl.formatMessage(messages.download)),
                anchor: e.currentTarget.getBoundingClientRect(),
                label,
                owner: popupOwner,
              },
              e.currentTarget,
            );
          }}
        />
      )}
    </div>
  );
}
