import { logEvent } from "./client";

// Client screens: every navigation starts a new screen, and visibility and
// gesture events are logged against the current screen's nonce.

let currentNonce: string | null = null;
const screenListeners = new Set<() => void>();

function makeNonce(): string {
  return btoa(String(Math.random())).replace(/=+$/, "");
}

export function currentScreen(): string | null {
  return currentNonce;
}

export function newScreen(): string {
  currentNonce = makeNonce();
  for (const l of screenListeners) l();
  logEvent("screenCreated", { csn: currentNonce, pageVe: { veType: 4724 } });
  return currentNonce;
}

export function onNewScreen(listener: () => void): () => void {
  screenListeners.add(listener);
  return () => screenListeners.delete(listener);
}
