import { flags } from "../flags";
import { track } from "../workload/idle";

// The simulated InnerTube network. Responses are pre-generated JSON texts,
// loaded before the app starts and served in order per response kind. A
// request is built as a real client builds it (JSON body, size check, gzip,
// Request object), then resolves with the response text in a later task.

const responses = new Map<string, string[]>();
const cursors = new Map<string, number>();

export type ResponseKind =
  | "search-init"
  | "search-append"
  | "search-reload"
  | "watch"
  | "comments-reload"
  | "comments-append"
  | "related-append"
  | "browse"
  | "grid-append"
  | "player"
  | "log";

export async function loadResponses(base: string, manifest: Partial<Record<ResponseKind, string[]>>): Promise<void> {
  await Promise.all(
    Object.entries(manifest).map(async ([kind, names]) => {
      const texts = await Promise.all(names.map((name) => fetch(`${base}/${name}.json`).then((res) => res.text())));
      responses.set(kind, texts);
      cursors.set(kind, 0);
    }),
  );
}

/** Rewinds every response list, for a fresh benchmark iteration. */
export function resetResponses(): void {
  for (const kind of cursors.keys()) cursors.set(kind, 0);
}

/** The UTF-8 size of a request body. */
export function byteLength(body: string): number {
  return new Blob([body]).size;
}

async function gzip(body: string): Promise<Uint8Array> {
  const stream = new Blob([body]).stream().pipeThrough(new CompressionStream("gzip"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

/** Gzips a POST body when its size is in the configured range. */
export async function prepareBody(body: string): Promise<{ body: string | Uint8Array; encoding: string | null }> {
  const size = byteLength(body);
  const min = flags.number("min_body_size_to_compress", 500);
  const max = flags.number("max_body_size_to_compress", 500000);
  if (size >= min && size <= max) return { body: await gzip(body), encoding: "gzip" };
  return { body, encoding: null };
}

function serve(kind: ResponseKind): string {
  const list = responses.get(kind) ?? [];
  const i = cursors.get(kind) ?? 0;
  cursors.set(kind, i + 1);
  return list.length ? list[i % list.length] : "{}";
}

/** Sends a POST request and resolves with the response text. */
export function post(kind: ResponseKind, apiPath: string, payload: unknown): Promise<string> {
  return track(
    (async () => {
      const { body, encoding } = await prepareBody(JSON.stringify(payload));
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        "X-Youtube-Client-Name": "1",
        "X-Youtube-Client-Version": "1.0.0",
      };
      if (encoding) headers["Content-Encoding"] = encoding;
      const request = new Request(`https://www.example.invalid${apiPath}?prettyPrint=false`, {
        method: "POST",
        headers,
        body: body as BodyInit,
        credentials: "include",
      });
      const text = kind === "log" ? "{}" : serve(kind);
      await new Promise((resolve) => setTimeout(resolve, 0));
      // The simulated server doesn't read the request. This use keeps the
      // minifier from dropping its construction, which a real fetch needs.
      return request.method === "POST" ? text : "";
    })(),
  );
}
