import { useId, useRef } from "react";
import type { ButtonRenderer as ButtonRendererData } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { getText, accessibilityLabel } from "../../model/text";
import { useImpression, logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { ButtonShape, type ButtonStyle, type ButtonType } from "./ButtonShape";
import { Tooltip } from "../feedback/Tooltip";
import styles from "./ButtonRenderer.module.css";

/** The style and type of a legacy button style. */
function shapeOf(style: ButtonRendererData["style"]): { buttonStyle: ButtonStyle; type: ButtonType } {
  switch (style) {
    case "STYLE_SUGGESTIVE":
      return { buttonStyle: "outline", type: "suggestive" };
    case "STYLE_MONO_FILLED":
    case "STYLE_BRAND":
    case "STYLE_DESTRUCTIVE":
      return { buttonStyle: "filled", type: "mono" };
    case "STYLE_MONO_OUTLINE":
    case "STYLE_INACTIVE_OUTLINE":
      return { buttonStyle: "outline", type: "mono" };
    case "STYLE_BLUE_TEXT":
      return { buttonStyle: "text", type: "callToAction" };
    case "STYLE_DEFAULT":
    case "STYLE_COMPACT_GRAY":
    case "STYLE_OPACITY":
      return { buttonStyle: "tonal", type: "mono" };
    default:
      return { buttonStyle: "text", type: "mono" };
  }
}

export interface ButtonRendererProps {
  data: ButtonRendererData;
  onClick?: () => void;
  className?: string;
  expanded?: boolean;
}

/** A legacy InnerTube buttonRenderer. */
export function ButtonRenderer({ data, onClick, className, expanded }: ButtonRendererProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const tooltipId = useId();
  const inner = data.buttonRenderer ?? data;
  const text = getText(inner.text);
  const label = inner.accessibility?.label || accessibilityLabel(inner.accessibilityData as { accessibilityData?: { label?: string } }) || text;
  const { buttonStyle, type } = shapeOf(inner.style);
  return (
    <div ref={ref} className={styles.host}>
      <ButtonShape
        className={className}
        text={text}
        icon={inner.icon?.iconType}
        iconPosition={inner.iconPosition === "BUTTON_ICON_POSITION_TYPE_RIGHT_OF_TEXT" ? "trailing" : "leading"}
        buttonStyle={buttonStyle}
        type={type}
        size={inner.size === "SIZE_SMALL" ? "s" : "m"}
        label={label || undefined}
        title={inner.tooltip ? undefined : text || undefined}
        describedBy={inner.tooltip ? tooltipId : undefined}
        disabled={inner.isDisabled}
        expanded={expanded}
        onClick={() => {
          logClick(inner);
          if (onClick) onClick();
          else runCommand((inner.command ?? inner.navigationEndpoint ?? inner.serviceEndpoint) as Endpoint | undefined);
        }}
      />
      <Tooltip text={inner.tooltip ?? ""} id={tooltipId} />
    </div>
  );
}
