export interface ClientContext {
  client: Record<string, unknown> & { mainAppWebInfo?: Record<string, unknown> };
  clickTracking?: { clickTrackingParams?: string };
  [key: string]: unknown;
}

export interface PageConfig {
  EXPERIMENT_FLAGS: Record<string, unknown>;
  INNERTUBE_CONTEXT: ClientContext;
  INNERTUBE_CLIENT_NAME: string;
  EVENT_ID: string;
  HTML_DIR: "ltr" | "rtl";
}

let config: PageConfig | null = null;

/**
 * The page config that the server inlines into a real page. Here it is a
 * static file, loaded once before the app renders.
 */
export async function loadConfig(base: string): Promise<PageConfig> {
  const res = await fetch(`${base}/config.json`);
  config = (await res.json()) as PageConfig;
  return config;
}

export function getConfig(): PageConfig {
  if (!config) throw new Error("page config not loaded");
  return config;
}
