import clsx from "clsx";
import type { MetadataBadgeRenderer } from "../../model/innertube.gen";
import { BadgeShape, type BadgeStyle } from "./BadgeShape";
import styles from "./MetadataBadge.module.css";

const STYLES: Record<string, BadgeStyle> = {
  BADGE_STYLE_TYPE_LIVE_NOW: "live",
  BADGE_STYLE_TYPE_MEDIA: "media",
  BADGE_STYLE_TYPE_SIMPLE: "simple",
  BADGE_STYLE_TYPE_VERIFIED: "verified",
  BADGE_STYLE_TYPE_VERIFIED_ARTIST: "verified",
};

export function isVerifiedBadge(badge: MetadataBadgeRenderer): boolean {
  return badge.style === "BADGE_STYLE_TYPE_VERIFIED" || badge.style === "BADGE_STYLE_TYPE_VERIFIED_ARTIST";
}

/** A legacy metadata badge (verified, live, 4K, CC...). */
export function MetadataBadge({ data }: { data: MetadataBadgeRenderer }) {
  const badgeStyle = STYLES[data.style] ?? "default";
  const iconOnly = badgeStyle === "verified" || badgeStyle === "media";
  return (
    <div className={clsx(styles.item, data.style === "BADGE_STYLE_TYPE_VERIFIED_ARTIST" && styles.artist)}>
      <BadgeShape
        text={data.label ?? ""}
        icon={data.icon?.iconType}
        badgeStyle={badgeStyle}
        label={data.accessibilityData?.label ?? data.tooltip ?? data.label}
        hideText={iconOnly && !!data.icon}
      />
    </div>
  );
}

export interface BadgeListProps {
  badges: Array<{ metadataBadgeRenderer?: MetadataBadgeRenderer }> | null | undefined;
  className?: string;
  /** Leaves out verified badges, which a channel name shows itself. */
  skipVerified?: boolean;
}

export function BadgeList({ badges, className, skipVerified }: BadgeListProps) {
  const list = (badges ?? []).flatMap((b) => (b.metadataBadgeRenderer ? [b.metadataBadgeRenderer] : []));
  const shown = skipVerified ? list.filter((b) => !isVerifiedBadge(b)) : list;
  if (!shown.length) return null;
  return (
    <div className={clsx(styles.list, className)}>
      {shown.map((badge) => (
        <MetadataBadge key={badge.trackingParams} data={badge} />
      ))}
    </div>
  );
}
