import clsx from "clsx";
import styles from "./Tooltip.module.css";

export interface TooltipProps {
  text: string;
  /** Set it to the aria-describedby of the element that the tooltip describes. */
  id?: string;
  position?: "top" | "bottom";
  className?: string;
}

/**
 * A tooltip that shows when its parent is hovered or focused. With an id, it
 * describes another element for screen readers; without one, it is only
 * visual.
 */
export function Tooltip({ text, id, position = "bottom", className }: TooltipProps) {
  if (!text) return null;
  return (
    <div id={id} role={id ? "tooltip" : undefined} aria-hidden={id ? undefined : true} className={clsx(styles.host, styles[position], className)}>
      <div className={styles.tooltip}>{text}</div>
    </div>
  );
}
