import type { Root } from "react-dom/client";
import { queryClient } from "../api/queryClient";

// Idle tracking for the benchmark steps. A step ends when the app has no
// tracked async work (simulated requests, IndexedDB writes, timers, lazy
// chunk loads), no query is fetching, React has no pending work on its root
// (no scheduled render, no pending lane: this covers transitions, deferred
// values and hidden Activity content), and a frame and a task have passed,
// so that passive effects and IntersectionObserver callbacks have run.

interface FiberRoot {
  pendingLanes: number;
  callbackNode: unknown;
}

let fiberRoot: FiberRoot | null = null;

/** Lets whenIdle() see the React root's pending work (a private field of React DOM). */
export function trackReactRoot(root: Root): void {
  fiberRoot = (root as unknown as { _internalRoot: FiberRoot })._internalRoot;
}

const pending = new Set<Promise<unknown>>();
let version = 0;

export function track<T>(promise: Promise<T>): Promise<T> {
  pending.add(promise);
  version++;
  const done = () => {
    pending.delete(promise);
  };
  promise.then(done, done);
  return promise;
}

/** A setTimeout that whenIdle() waits for. */
export function trackedTimeout(fn: () => void, ms: number): () => void {
  let cancel!: () => void;
  const promise = new Promise<void>((resolve) => {
    const id = setTimeout(() => {
      resolve();
      fn();
    }, ms);
    cancel = () => {
      clearTimeout(id);
      resolve();
    };
  });
  track(promise);
  return cancel;
}

function nextTask(): Promise<void> {
  return new Promise((resolve) => {
    const channel = new MessageChannel();
    channel.port1.onmessage = () => resolve();
    channel.port2.postMessage(null);
  });
}

function nextFrame(): Promise<void> {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()));
}

function isIdle(): boolean {
  const reactIdle = !fiberRoot || (fiberRoot.pendingLanes === 0 && fiberRoot.callbackNode === null);
  return pending.size === 0 && queryClient.isFetching() === 0 && queryClient.isMutating() === 0 && reactIdle;
}

export async function whenIdle(): Promise<void> {
  for (;;) {
    const start = version;
    while (pending.size) await Promise.allSettled([...pending]);
    await nextFrame();
    await nextTask();
    if (isIdle() && version === start) return;
  }
}
