import { useId, useRef } from "react";
import type { ButtonViewModel as ButtonViewModelData } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { useImpression } from "../../logging/impressions";
import { logClick } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { ButtonShape, type ButtonSize, type ButtonStyle, type ButtonType } from "./ButtonShape";
import { Tooltip } from "../feedback/Tooltip";
import styles from "./ButtonViewModel.module.css";

const TYPES: Record<string, ButtonStyle> = {
  BUTTON_VIEW_MODEL_TYPE_FILLED: "filled",
  BUTTON_VIEW_MODEL_TYPE_TONAL: "tonal",
  BUTTON_VIEW_MODEL_TYPE_OUTLINE: "outline",
  BUTTON_VIEW_MODEL_TYPE_TEXT: "text",
};

const SIZES: Record<string, ButtonSize> = {
  BUTTON_VIEW_MODEL_SIZE_DEFAULT: "m",
  BUTTON_VIEW_MODEL_SIZE_LARGE: "m",
  BUTTON_VIEW_MODEL_SIZE_COMPACT: "s",
  BUTTON_VIEW_MODEL_SIZE_XSMALL: "xs",
};

function buttonType(style: ButtonViewModelData["style"]): ButtonType {
  switch (style) {
    case "BUTTON_VIEW_MODEL_STYLE_OVERLAY":
    case "BUTTON_VIEW_MODEL_STYLE_OVERLAY_DARK":
      return "overlay";
    default:
      return "mono";
  }
}

/** The command that tapping the button runs. */
export function tapCommand(data: ButtonViewModelData): Endpoint | undefined {
  return (data.onTap?.innertubeCommand as Endpoint | undefined) ?? (data.onTap as Endpoint | undefined);
}

export interface ButtonViewModelProps {
  data: ButtonViewModelData;
  /** Overrides the command that onTap would run. */
  onClick?: () => void;
  className?: string;
  pressed?: boolean;
}

/** A button described by an InnerTube buttonViewModel. */
export function ButtonViewModel({ data, onClick, className, pressed }: ButtonViewModelProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const tooltipId = useId();
  const text = data.title;
  const label = data.accessibilityText ?? (text ? undefined : data.tooltip);
  return (
    <div ref={ref} className={styles.host}>
      <ButtonShape
        className={className}
        text={text}
        icon={data.iconName}
        iconPosition={data.iconPosition === "BUTTON_VIEW_MODEL_ICON_POSITION_TRAILING" ? "trailing" : "leading"}
        buttonStyle={TYPES[data.type ?? ""] ?? "text"}
        type={buttonType(data.style)}
        size={SIZES[data.buttonSize ?? ""] ?? "m"}
        label={label}
        title={data.tooltip ? undefined : text}
        describedBy={data.tooltip ? tooltipId : undefined}
        fullWidth={data.isFullWidth}
        pressed={pressed}
        onClick={() => {
          logClick(data);
          if (onClick) onClick();
          else runCommand(tapCommand(data));
        }}
      />
      {data.tooltip && <Tooltip text={data.tooltip} id={tooltipId} />}
    </div>
  );
}
