import type { AnchorHTMLAttributes, MouseEvent, ReactNode, Ref } from "react";
import { Link } from "react-router";
import { endpointHref, type Endpoint } from "../../model/endpoints";
import { logClick } from "../../logging/impressions";

export interface EndpointLinkProps extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> {
  endpoint: Endpoint | null | undefined;
  children?: ReactNode;
  ref?: Ref<HTMLAnchorElement>;
}

/**
 * A link for an InnerTube endpoint: a router link for pages of this app,
 * else a plain link to the server's URL. Clicks are logged as gestures.
 */
export function EndpointLink({ endpoint, children, onClick, ...rest }: EndpointLinkProps) {
  const href = endpointHref(endpoint);
  const handleClick = (e: MouseEvent<HTMLAnchorElement>) => {
    logClick(endpoint ? { trackingParams: endpoint.clickTrackingParams } : null);
    onClick?.(e);
  };
  if (href) {
    return (
      <Link to={href} state={{ endpoint }} onClick={handleClick} {...rest}>
        {children}
      </Link>
    );
  }
  const url = endpoint?.commandMetadata?.webCommandMetadata?.url ?? endpoint?.urlEndpoint?.url;
  return (
    <a href={url} onClick={handleClick} {...rest}>
      {children}
    </a>
  );
}
