export type StepEvent = "navigate-finish" | "continuation-applied" | "reload-applied";

/**
 * Signals the benchmark that the content of a response has been committed.
 * Called from effects, so it runs after the commit that shows the content.
 */
export function emitStepEvent(name: StepEvent, targetId?: string): void {
  window.dispatchEvent(new CustomEvent(`ytr-${name}`, { detail: { targetId } }));
}

/**
 * Resolves on the next `name` event, or, with `targetIds`, once an event has
 * come for each of them. The same contract as the realistic version's.
 */
export function nextEvent(name: string, targetIds?: string[] | null): Promise<void> {
  if (!targetIds) return new Promise((resolve) => window.addEventListener(name, () => resolve(), { once: true }));
  const waiting = new Set(targetIds);
  return new Promise((resolve) => {
    const listener = (e: Event) => {
      waiting.delete((e as CustomEvent<{ targetId?: string }>).detail?.targetId ?? "");
      if (waiting.size) return;
      window.removeEventListener(name, listener);
      resolve();
    };
    window.addEventListener(name, listener);
  });
}
