import { flags } from "../flags";
import { logEvent } from "./client";
import { currentScreen } from "./screen";

// Performance telemetry: latency actions per navigation, service-level
// indicators for requests and navigations, counters, and a foreground
// heartbeat. Everything is sent through the logging client.

function randomId(n: number): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  let out = "";
  for (let i = 0; i < n; i++) out += alphabet[Math.floor(Math.random() * alphabet.length)];
  return out;
}

// Latency actions

export type LatencyAction = "results" | "watch" | "browse";
const ACTION_TYPES: Record<LatencyAction, string> = {
  results: "LATENCY_ACTION_RESULTS",
  watch: "LATENCY_ACTION_WATCH",
  browse: "LATENCY_ACTION_BROWSE",
};

let actionNonce = randomId(16);
const infoCounts = new Map<string, number>();

function latencyInfo(info: Record<string, unknown>) {
  const key = `${Object.keys(info).join("")}_${actionNonce}`;
  const n = (infoCounts.get(key) ?? 0) + 1;
  infoCounts.set(key, n);
  if (n > 5) return;
  logEvent("latencyActionInfo", { ...info, clientActionNonce: actionNonce });
}

/** Starts the latency action of a navigation, after its screen was created. */
export function startLatencyAction(action: LatencyAction): void {
  actionNonce = randomId(16);
  const csn = currentScreen();
  latencyInfo({ actionType: ACTION_TYPES[action], ...(csn ? { clientScreenNonce: csn } : {}) });
  latencyInfo({ loadType: "warm" });
  if (csn) latencyInfo({ clientScreenNonce: csn });
}

// Service-level indicators

interface SliEvent {
  name: string;
  dimensions: Record<string, unknown>;
  records: Array<{ status: string; durationMs: number }>;
}

/** A started service-level indicator measurement. */
export interface SliTiming {
  name: string;
  start: number;
  dimensions: Record<string, unknown>;
}

const sliEvents = new Map<string, SliEvent>();
let sliCount = 0;
let sliTimer = 0;

function flushSlis() {
  clearInterval(sliTimer);
  sliTimer = 0;
  if (!sliCount) return;
  if (flags.bool("enable_client_sli_logging")) logEvent("sliEventBatch", { loggedEvents: [...sliEvents.values()] });
  sliEvents.clear();
  sliCount = 0;
}

function sliStart(name: string, dimensions: Record<string, unknown>): SliTiming {
  return { name, start: performance.now(), dimensions };
}

function sliEnd(started: SliTiming, status: string) {
  const { name } = started;
  const dimensions = { ...started.dimensions, csn: currentScreen() ?? "" };
  const key = `${name};${JSON.stringify(dimensions)}`;
  const record = { status, durationMs: Math.round(performance.now() - started.start) };
  const event = sliEvents.get(key);
  if (event) event.records.push(record);
  else sliEvents.set(key, { name, dimensions, records: [record] });
  if (!sliTimer) sliTimer = window.setInterval(flushSlis, 30000);
  if (++sliCount >= 100) flushSlis();
}

const pageDimensions = (page: string, request: string) => ({
  pageType: `MAIN_APP_WEB_PAGE_TYPE_${page.toUpperCase()}`,
  requestType: `MAIN_APP_WEB_REQUEST_TYPE_${request.toUpperCase()}`,
});

export function networkRequestStarted(page: string, request: "navigation" | "continuation"): SliTiming {
  return sliStart("SLI_NAME_YOUTUBE_WEB_NETWORK_REQUEST", pageDimensions(page, request));
}

export function networkRequestFinished(request: SliTiming, ok: boolean): void {
  sliEnd(request, ok ? "SUCCESS" : "FAILURE");
}

let navigation: SliTiming | null = null;

export function navigationStarted(page: string): void {
  navigation = sliStart("SLI_NAME_YOUTUBE_WEB_WARM_PAGE_NAVIGATION", pageDimensions(page, "browse"));
}

/** Ends the navigation that navigationStarted() began, once. */
export function navigationFinished(): void {
  if (!navigation) return;
  sliEnd(navigation, "SUCCESS");
  navigation = null;
}

// Counters

const counters = new Map<string, number>();
let counterInvocations = 0;
let counterTimer = 0;

function flushCounters() {
  clearInterval(counterTimer);
  counterTimer = 0;
  if (counters.size && flags.bool("enable_client_streamz_web")) {
    logEvent("streamzIncremented", { increments: Object.fromEntries(counters) });
  }
  counters.clear();
  counterInvocations = 0;
}

function incrementCounter(name: string) {
  counters.set(name, (counters.get(name) ?? 0) + 1);
  if (!counterTimer) counterTimer = window.setInterval(flushCounters, 30000);
  if (++counterInvocations >= flags.number("client_streamz_web_flush_count", 100)) flushCounters();
}

export function countResponse(status: "ok" | "missing"): void {
  incrementCounter(`/client_streamz/youtube/web/response_signature/${status}`);
  incrementCounter("/client_streamz/youtube/web/e_sig_log/search/true");
}

// Foreground heartbeat

const documentNonce = randomId(16);
const pageStart = Date.now();
let heartbeatIndex = 0;
let lastHeartbeat = 0;

function heartbeat(trigger: string) {
  if (trigger.endsWith("ON_INTERVAL") && document.visibilityState !== "visible") return;
  logEvent("foregroundHeartbeat", {
    firstActivityMs: String(heartbeatIndex ? -1 : Date.now() - pageStart),
    clientDocumentNonce: documentNonce,
    index: String(heartbeatIndex++),
    lastEventDeltaMs: String(lastHeartbeat ? Math.round(performance.now() - lastHeartbeat) : -1),
    trigger,
  });
  lastHeartbeat = performance.now();
}

export function startHeartbeat(): void {
  heartbeat("FOREGROUND_HEARTBEAT_TRIGGER_ON_FOREGROUND");
  setInterval(() => heartbeat("FOREGROUND_HEARTBEAT_TRIGGER_ON_INTERVAL"), 30000);
  document.addEventListener("visibilitychange", () => {
    heartbeat(document.visibilityState === "hidden" ? "FOREGROUND_HEARTBEAT_TRIGGER_ON_BACKGROUND" : "FOREGROUND_HEARTBEAT_TRIGGER_ON_FOREGROUND");
  });
}
