import { getConfig } from "./config";

/**
 * Typed lookups of the experiment flags in the page config. Flags that are
 * off are absent, so every lookup has a default.
 */
export const flags = {
  bool(name: string, fallback = false): boolean {
    const v = getConfig().EXPERIMENT_FLAGS[name];
    if (v === undefined) return fallback;
    return v === true || v === "true";
  },
  number(name: string, fallback = 0): number {
    const v = Number(getConfig().EXPERIMENT_FLAGS[name]);
    return Number.isFinite(v) && v !== 0 ? v : fallback;
  },
  string(name: string, fallback = ""): string {
    const v = getConfig().EXPERIMENT_FLAGS[name];
    return typeof v === "string" ? v : fallback;
  },
};
