import { useEffect, type RefObject } from "react";
import { trackingParamsOf, type LoggingDirectives } from "../model/endpoints";
import { logEvent } from "./client";
import { currentScreen, onNewScreen } from "./screen";

// Impression logging. Components with server tracking params register
// their root element; one IntersectionObserver reports when they enter
// and leave the viewport. Shown and hidden events are deduplicated per
// screen by tracking params, following the element's logging directives:
// visibility types 1 (shown once), 2 (hidden once), 4 (shown every time)
// and 8 (hidden every time).

export type Loggable = object;

interface Registration {
  trackingParams: string;
  types: number;
  hasDirectives: boolean;
}

class VisibilityLogger {
  private shown = new Set<string>();
  private hidden = new Set<string>();
  private visible = new Map<string, boolean>();

  constructor() {
    onNewScreen(() => {
      this.shown.clear();
      this.hidden.clear();
      this.visible.clear();
    });
  }

  reportShown(el: Element, r: Registration) {
    const key = r.trackingParams;
    const wasShown = this.shown.has(key);
    const visible = this.visible.get(key) === true;
    if (wasShown && visible) return;
    this.shown.add(key);
    this.visible.set(key, true);
    const csn = currentScreen();
    if (!csn) return;
    let eventType = 0;
    if (r.hasDirectives || wasShown) {
      if (r.types & 4) eventType = visible ? 0 : 4;
      else if (r.types & 1 && !wasShown) eventType = 1;
    } else eventType = 1;
    if (eventType) {
      logEvent(
        "visualElementShown",
        { csn, ve: { trackingParams: key }, eventType, clientData: { viewData: viewData(el) } },
        { sequenceGroup: csn },
      );
    }
  }

  reportHidden(r: Registration) {
    const key = r.trackingParams;
    const wasHidden = this.hidden.has(key);
    const visible = this.visible.get(key);
    this.hidden.add(key);
    this.visible.set(key, false);
    if (visible === false) return;
    const csn = currentScreen();
    if (!csn) return;
    let eventType = 0;
    if (r.types & 8) eventType = 8;
    else if (r.types & 2 && !wasHidden) eventType = 2;
    if (eventType) logEvent("visualElementHidden", { csn, ve: { trackingParams: key }, eventType }, { sequenceGroup: csn });
  }
}

const logger = new VisibilityLogger();

/** The element's position in the viewport, and whether it is in a fixed container. */
function viewData(el: Element) {
  const rect = el.getBoundingClientRect();
  let position = "POSITION_UNSPECIFIED";
  for (let n: Element | null = el; n; n = n.parentElement) {
    if (getComputedStyle(n).position === "fixed") {
      position = "POSITION_FIXED";
      break;
    }
    if (n !== el && registrations.has(n)) break;
  }
  return {
    originXPoints: Math.round(rect.left),
    originYPoints: Math.round(rect.top),
    widthPoints: Math.round(rect.width),
    heightPoints: Math.round(rect.height),
    position,
  };
}

const registrations = new Map<Element, Registration>();
let observer: IntersectionObserver | null = null;

function sharedObserver(): IntersectionObserver {
  observer ??= new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        const r = registrations.get(entry.target);
        if (!r) continue;
        if (entry.isIntersecting) logger.reportShown(entry.target, r);
        else logger.reportHidden(r);
      }
    },
    { threshold: 0 },
  );
  return observer;
}

/**
 * Logs impressions of the element in `ref` for `data`, a renderer or view
 * model with tracking params. Does nothing for data without them.
 */
export function useImpression(ref: RefObject<Element | null>, data: Loggable | null | undefined): void {
  const trackingParams = trackingParamsOf(data);
  // The visibility types come from a renderer's own logging directives. View
  // models keep theirs in the renderer context, which only supplies the
  // tracking params, so a view model is logged when first shown.
  const directives = (data as { loggingDirectives?: LoggingDirectives } | null | undefined)?.loggingDirectives;
  const types = Math.floor(Number(directives?.visibility?.types ?? "")) || 1;
  const hasDirectives = !!directives;
  useEffect(() => {
    const el = ref.current;
    if (!el || !trackingParams) return;
    registrations.set(el, { trackingParams, types, hasDirectives });
    const obs = sharedObserver();
    obs.observe(el);
    return () => {
      obs.unobserve(el);
      registrations.delete(el);
    };
  }, [ref, trackingParams, types, hasDirectives]);
}

/** Logs a click on a visual element, as a gesture event. */
export function logClick(data: Loggable | null | undefined): void {
  const trackingParams = trackingParamsOf(data);
  const csn = currentScreen();
  if (!trackingParams || !csn) return;
  logEvent("visualElementGestured", { csn, ve: { trackingParams }, gestureType: "INTERACTION_LOGGING_GESTURE_TYPE_GENERIC_CLICK" });
}
