import clsx from "clsx";
import type { ElementType } from "react";
import { attributedRanges, type AttributedText } from "../../model/text";
import type { Endpoint } from "../../model/endpoints";
import { EndpointLink } from "./EndpointLink";
import styles from "./AttributedString.module.css";

export interface AttributedStringProps {
  text: AttributedText | string | null | undefined;
  className?: string;
  /** Links take the surrounding text color. */
  inheritLinkColor?: boolean;
  as?: ElementType;
}

interface RunStyle {
  weightLabel?: string;
  fontColor?: number;
  italic?: boolean;
  strikethrough?: string;
}

function argbToCss(argb: number): string {
  const a = ((argb >>> 24) & 255) / 255;
  return `rgba(${(argb >> 16) & 255}, ${(argb >> 8) & 255}, ${argb & 255}, ${a.toFixed(3)})`;
}

function inlineStyle(style: RunStyle): React.CSSProperties | undefined {
  const out: React.CSSProperties = {};
  if (style.weightLabel === "FONT_WEIGHT_MEDIUM") out.fontWeight = 500;
  else if (style.weightLabel === "FONT_WEIGHT_BOLD") out.fontWeight = 700;
  if (typeof style.fontColor === "number") out.color = argbToCss(style.fontColor);
  if (style.italic) out.fontStyle = "italic";
  if (style.strikethrough) out.textDecoration = "line-through";
  return Object.keys(out).length ? out : undefined;
}

/** An attributed string: content with style runs and command runs. */
export function AttributedString({ text, className, inheritLinkColor, as: Tag = "span" }: AttributedStringProps) {
  const attributed = typeof text === "string" ? { content: text } : text;
  const ranges = attributedRanges(attributed);
  return (
    <Tag className={clsx(styles.host, styles.preWrap, inheritLinkColor && styles.inheritColor, className)}>
      {ranges.length === 1 && !ranges[0].style && !ranges[0].command
        ? ranges[0].text
        : ranges.map((range, i) => {
            const style = range.style ? inlineStyle(range.style as RunStyle) : undefined;
            const command = range.command?.onTap as { innertubeCommand?: Endpoint } | undefined;
            if (command) {
              return (
                <EndpointLink key={i} endpoint={command.innertubeCommand ?? (command as Endpoint)} className={styles.link} style={style}>
                  {range.text}
                </EndpointLink>
              );
            }
            return style ? (
              <span key={i} style={style}>
                {range.text}
              </span>
            ) : (
              range.text
            );
          })}
    </Tag>
  );
}
