import clsx from "clsx";
import type { MouseEvent } from "react";
import { Icon } from "../icon/Icon";
import { TouchFeedback } from "../feedback/TouchFeedback";
import styles from "./IconButton.module.css";

export interface IconButtonProps {
  icon: string;
  label: string;
  describedBy?: string;
  className?: string;
  id?: string;
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
  expanded?: boolean;
  hasPopup?: boolean;
}

/** A round 40px button with a single icon. */
export function IconButton({ icon, label, describedBy, className, id, onClick, expanded, hasPopup }: IconButtonProps) {
  return (
    <div className={clsx(styles.host, className)} id={id}>
      <button
        type="button"
        className={styles.button}
        aria-label={label}
        aria-describedby={describedBy}
        aria-expanded={expanded}
        aria-haspopup={hasPopup || undefined}
        onClick={onClick}
      >
        <Icon icon={icon} />
      </button>
      <TouchFeedback className={styles.feedback} />
    </div>
  );
}
