import { create } from "zustand";
import type { Endpoint } from "../model/endpoints";

// UI state shared across the app: the guide, popups and engagement panels.

export interface MenuItem {
  text: string;
  icon?: string;
  command?: Endpoint;
  hasSeparator?: boolean;
  trackingParams?: string;
}

// A menu's `owner` identifies the button that opened it, for its aria-expanded.
export type Popup =
  | { kind: "menu"; items: MenuItem[]; anchor: DOMRect; label?: string; owner: string }
  | { kind: "dialog"; renderer: string; data: unknown };

export type OpenPopup = Popup & {
  /** The element that had focus when the popup opened; it gets focus back when the popup closes. */
  returnFocus: HTMLElement | null;
};

/**
 * The engagement panels that commands have shown or hidden, by panel id.
 * Only the watch page that claimed the panels (`owner`) reads them, so a
 * new watch page starts with the visibility from its response.
 */
export interface PanelState {
  owner: string | null;
  visible: Readonly<Record<string, boolean>>;
}

interface UiState {
  /** Whether the guide shows beside the pages, on pages that have room for it. */
  guideOpen: boolean;
  /** Whether the guide is open as a drawer over the page (on watch pages). */
  drawerOpen: boolean;
  popup: OpenPopup | null;
  panels: PanelState;
  toggleGuide: () => void;
  toggleDrawer: () => void;
  closeDrawer: () => void;
  /** Opens a popup. Focus returns to `trigger` on close, by default to the focused element. */
  openPopup: (popup: Popup, trigger?: HTMLElement) => void;
  closePopup: () => void;
  claimPanels: (owner: string) => void;
  releasePanels: (owner: string) => void;
  /** Shows a panel, which hides the others that a command showed, or hides one. */
  setPanelVisible: (id: string, visible: boolean) => void;
}

const NO_PANELS: PanelState = { owner: null, visible: {} };

export const useUiStore = create<UiState>()((set) => ({
  guideOpen: true,
  drawerOpen: false,
  popup: null,
  panels: NO_PANELS,
  toggleGuide: () => set((s) => ({ guideOpen: !s.guideOpen })),
  toggleDrawer: () => set((s) => ({ drawerOpen: !s.drawerOpen })),
  closeDrawer: () => set({ drawerOpen: false }),
  openPopup: (popup, trigger) => {
    const focused = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    set({ popup: { ...popup, returnFocus: trigger ?? focused } });
  },
  closePopup: () => set({ popup: null }),
  claimPanels: (owner) => set({ panels: { owner, visible: {} } }),
  releasePanels: (owner) => set((s) => (s.panels.owner === owner ? { panels: NO_PANELS } : s)),
  setPanelVisible: (id, visible) =>
    set((s) => ({ panels: { owner: s.panels.owner, visible: visible ? { [id]: true } : { ...s.panels.visible, [id]: false } } })),
}));
