// Commands and endpoints: their URLs in this app, the flattening of command
// wrappers, and their logging data.

export interface Endpoint {
  clickTrackingParams?: string;
  commandMetadata?: { webCommandMetadata?: { url?: string; webPageType?: string; apiUrl?: string } };
  watchEndpoint?: { videoId?: string; playerParams?: string; params?: string };
  browseEndpoint?: { browseId?: string; params?: string; canonicalBaseUrl?: string };
  searchEndpoint?: { query?: string; params?: string };
  reelWatchEndpoint?: { videoId?: string };
  urlEndpoint?: { url?: string };
  continuationCommand?: { token?: string; request?: string };
  commandExecutorCommand?: { commands?: Endpoint[] };
  innertubeCommand?: Endpoint;
  [key: string]: unknown;
}

export interface ChannelPath {
  /** The handle (with its @) or the channel id. */
  channel: string;
  /** The tab segment, such as "videos"; null for the channel's home. */
  tab: string | null;
}

/** The channel and tab of a channel URL (/@handle[/tab] or /channel/<id>[/tab]), or null. */
export function parseChannelPath(pathname: string): ChannelPath | null {
  const m = /^\/(?:(@[^/]+)|channel\/([^/]+))(?:\/([^/]+))?\/?$/.exec(pathname);
  if (!m) return null;
  return { channel: m[1] ?? m[2], tab: m[3] ?? null };
}

export function isChannelPath(pathname: string): boolean {
  return parseChannelPath(pathname) !== null;
}

/**
 * The in-app URL of a navigation endpoint, relative to the router's base,
 * or null when it doesn't navigate within the app.
 */
export function endpointHref(endpoint: Endpoint | null | undefined): string | null {
  if (!endpoint) return null;
  if (endpoint.watchEndpoint?.videoId) return `/watch?v=${endpoint.watchEndpoint.videoId}`;
  if (endpoint.reelWatchEndpoint?.videoId) return `/shorts/${endpoint.reelWatchEndpoint.videoId}`;
  if (endpoint.searchEndpoint) return `/results?search_query=${encodeURIComponent(endpoint.searchEndpoint.query ?? "")}`;
  if (endpoint.browseEndpoint) {
    const url = endpoint.commandMetadata?.webCommandMetadata?.url;
    if (url && isChannelPath(url)) return url;
    const base = endpoint.browseEndpoint.canonicalBaseUrl;
    return base && base.startsWith("/@") ? base : `/channel/${endpoint.browseEndpoint.browseId ?? ""}`;
  }
  return null;
}

/** The URL to show for an endpoint: the in-app route, else the server's URL. */
export function endpointUrl(endpoint: Endpoint | null | undefined): string {
  return endpointHref(endpoint) ?? endpoint?.commandMetadata?.webCommandMetadata?.url ?? endpoint?.urlEndpoint?.url ?? "";
}

export function flattenCommand(command: Endpoint | null | undefined): Endpoint[] {
  if (!command) return [];
  if (command.innertubeCommand) return flattenCommand(command.innertubeCommand);
  if (command.commandExecutorCommand) return (command.commandExecutorCommand.commands ?? []).flatMap(flattenCommand);
  return [command];
}

export interface LoggingDirectives {
  trackingParams?: string;
  visibility?: { types?: string };
  gestures?: { types?: string };
}

/** The logging directives of renderer or view-model data, wherever they are. */
export function loggingDirectivesOf(data: unknown): LoggingDirectives | undefined {
  const d = data as { loggingDirectives?: LoggingDirectives; rendererContext?: { loggingContext?: { loggingDirectives?: LoggingDirectives } } } | null | undefined;
  return d?.rendererContext?.loggingContext?.loggingDirectives ?? d?.loggingDirectives;
}

export function trackingParamsOf(data: unknown): string {
  const d = data as { trackingParams?: unknown; clickTrackingParams?: unknown } | null | undefined;
  if (!d) return "";
  const directives = loggingDirectivesOf(d);
  if (typeof directives?.trackingParams === "string") return directives.trackingParams;
  if (typeof d.trackingParams === "string") return d.trackingParams;
  if (typeof d.clickTrackingParams === "string") return d.clickTrackingParams;
  return "";
}
